static void xelavie_audit_pass(void *priv, const struct pl_render_info *info)
{
    if (!getenv("XELAVIE_AUDIT_SHADERS")) return;
    const struct pl_dispatch_info *p = info->pass;
    av_log(priv, AV_LOG_WARNING, "XELAVIE_AUDIT_PASS stage=%d index=%d last_ns=%llu description=%s\n",
        info->stage, info->index, (unsigned long long) p->last,
        p->shader ? p->shader->description : "unknown");
}
